		LmdbStoreConnection connection = (LmdbStoreConnection) store.getConnection();
		connection.begin(IsolationLevels.SNAPSHOT);
		RuntimeException firstFailure = new IllegalStateException("first delegate close failed");
		RuntimeException secondFailure = new IllegalArgumentException("second delegate close failed");
		RuntimeException operationFailure = new UnsupportedOperationException("owning read failed");
		AtomicInteger firstCloses = new AtomicInteger();
		AtomicInteger secondCloses = new AtomicInteger();
		AtomicInteger thirdCloses = new AtomicInteger();
		List<CloseableIteration<String>> queued = List.of(
				connection.registerIteration(new Delegate(firstCloses, firstFailure)),
				connection.registerIteration(new Delegate(secondCloses, secondFailure)),
				connection.registerIteration(new Delegate(thirdCloses, null)));
		AtomicBoolean trigger = new AtomicBoolean(drain.name().startsWith("TRACKED"));
		AtomicReference<QueryExecutionContext.ReplayContext> captured = new AtomicReference<>();
		Runnable closeAll = () -> {
			queued.forEach(CloseableIteration::close);
			if (drain.name().endsWith("FAILURE")) {
				throw operationFailure;
			}
		};
		CloseableIteration<String> owner = connection.registerIteration(new Delegate(new AtomicInteger(), null) {
			@Override
			public boolean hasNext() {
				if (trigger.get()) {
					closeAll.run();
				} else {
					captured.set(QueryExecutionContext.captureReplayContext());
				}
				return true;
			}
		});
		if (!drain.name().startsWith("TRACKED")) {
			assertThat(owner.hasNext()).isTrue();
			trigger.set(true);
		}
		Throwable observed = null;
		try {
			if (drain.name().startsWith("WORKER")) {
				try (var executor = Executors.newSingleThreadExecutor()) {
					executor.submit(() -> captured.get().run(closeAll)).get(5, TimeUnit.SECONDS);
				}
			} else {
				owner.hasNext();
			}
		} catch (Throwable failure) {
			observed = failure instanceof ExecutionException ? failure.getCause() : failure;
		}
		System.out.println("DELEGATE_CLOSE_COUNTS " + firstCloses + ' ' + secondCloses + ' ' + thirdCloses);
		// A failed contract may leave an unreachable queued native owner. The child exits on assertion failure;
		// attempting connection shutdown in that broken state would hide the original failure behind a self-wait.
