		assertThat(secondCloses).hasValue(1);
		assertThat(thirdCloses).hasValue(1);
		if (drain.name().endsWith("FAILURE")) {
			assertThat(observed).isSameAs(operationFailure);
			if (drain == Drain.WORKER_FAILURE) {
				// ReplayContext keeps the failing action primary and attaches the scope's aggregate cleanup failure.
				assertThat(observed.getSuppressed()).containsExactly(firstFailure);
				assertThat(firstFailure.getSuppressed()).containsExactly(secondFailure);
			} else {
				assertThat(observed.getSuppressed()).containsExactly(firstFailure, secondFailure);
			}
		} else {
			assertThat(observed).isSameAs(firstFailure);
			assertThat(observed.getSuppressed()).containsExactly(secondFailure);
		}
		owner.close();
		connection.rollback();
		connection.close();
		store.shutDown();
		System.out.println("DELEGATES_RELEASED " + drain);
